      const _faltaSuCiudad = String(ctx.zona_entrega ?? "") === "provincia" &&
        (!String(ctx.ciudad ?? "").trim() || esSoloDepartamento(String(ctx.ciudad ?? "")));
      // 🗣️ …y tampoco es el turno si el cliente PREGUNTÓ por las oficinas. Ese turno es suyo:
