        const _lblTal = String(_falta1?.label ?? "").replace(/[¿?¡!]/g, "")
          .replace(/\bsus\b/gi, "tus").replace(/\bsu\b/gi, "tu").trim();
        const _lbl = _lblTal.toLowerCase();
        // 💻 En digital el remate depende de en qué va: si ya dijo que pagó o ya tiene el
