        salida = salida.trimEnd() + `\n\nAh, y confírmame que es *${_d}* de Lima 🙂`;
        await setField(db, run.channel_id, run.contact_id, "distrito_ambiguo", "").catch(() => {});
        delete (ctx as any).distrito_ambiguo;
